{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Bupropion, the highest-transfer reference, has a rat brain ECF/plasma unbound concentration ratio (Kp,uu) of 1.9 by quantitative microdialysis, demonstrating meaningful net CNS uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hydroxybupropion, with a nearly identical transfer score, also equilibrates rapidly across the BBB with a Kp,uu of 1.7, supporting CNS access for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ketamine in healthy humans has a CSF:plasma ratio of 0.917, directly showing extensive CNS penetration after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "(S)-Ketamine in rats achieves brain:plasma ratios of 5.7-12.3 from 10 to 60 minutes after i.v. dosing, confirming rapid and sustained brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Clofoctol, a lipophilic dichlorophenyl-containing compound, reaches 152-187 ng/g in mouse brain after i.v. dosing, supporting CNS penetration for dichlorophenyl-substituted molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A-834735 readily crosses the BBB and produces central pharmacodynamic changes in rat brain regions, supporting CNS access for heteroaromatic drug-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence points to meaningful CNS access: multiple direct measurements (Kp,uu >1, CSF:plasma ~0.9, brain:plasma >5) and in vivo brain uptake studies support a pass prediction for the query.",
  "evidence_gaps": [
    "No direct Kp,uu, CSF, or brain/plasma measurement for the query molecule itself.",
    "No explicit efflux-transporter (P-gp/BCRP) or unbound brain concentration data for the query.",
    "Transfer scores are assay-based rather than structural-similarity scores, so structural extrapolation is indirect."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "CNS penetrant reference"
    }
  ],
  "revision_action": "initial"
}

